application.css:
* { box-sizing: border-box; }

:root {
  color: #172033;
  background: #eef2f7;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body { margin: 0; }
.page-shell { width: min(100% - 2rem, 48rem); margin: 0 auto; padding: 2rem 0 3rem; }
.page-header { margin-bottom: 1.5rem; }
h1, h2 { line-height: 1.2; }
h1 { margin: 0 0 .5rem; color: #102a43; }
.page-header p { margin: 0; }
.question-card { min-inline-size: 0; margin: 0 0 1rem; padding: 1rem; border: 1px solid #b8c4d3; border-radius: .6rem; background: #fff; }
legend { max-width: 100%; padding: 0 .35rem; font-weight: 700; }
.options { display: grid; gap: .65rem; margin-top: .65rem; }
.option { display: flex; align-items: center; gap: .65rem; padding: .7rem; border: 1px solid #9aaabd; border-radius: .4rem; cursor: pointer; }
.option:hover { background: #f1f6fb; }
.option:has(input:checked) { border-color: #155e75; background: #e3f4f7; }
input { inline-size: 1.1rem; block-size: 1.1rem; accent-color: #155e75; }
button { font: inherit; }
.submit-button { margin-top: .5rem; padding: .7rem 1.2rem; border: 0; border-radius: .4rem; color: #fff; background: #155e75; font-weight: 700; cursor: pointer; }
.submit-button:hover { background: #0e4759; }
:focus-visible { outline: 3px solid #f59e0b; outline-offset: 3px; }
.message { margin: 1rem 0 0; color: #9b1c1c; font-weight: 700; }
.result { margin-top: 1.5rem; padding: 1rem; border-radius: .6rem; background: #d9f2e6; }
.result h2 { margin: 0 0 .35rem; font-size: 1.2rem; }
.result p { margin: 0; font-size: 1.1rem; font-weight: 700; }
[hidden] { display: none; }

@media (max-width:  thirtyrem) {
  .page-shell { width: min(100% - 1rem, 48rem); padding-top: 1.25rem; }
}

application.javascript:
const form = document.querySelector('#quiz-form');
const message = document.querySelector('#form-message');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const scoreValue = document.querySelector('#score-value');
const resultHeading = document.querySelector('#result-heading');

const answers = Object.freeze({ q1: 'mars', q2: 'pacific', q3: 'html' });
const questionNames = Object.keys(answers);

function getSelectedValue(name) {
  const selected = form.querySelector(`input[name="${name}"]:checked`);
  return selected ? selected.value : null;
}

function showValidationError() {
  message.textContent = 'Please select one answer for every question.';
  message.hidden = false;
}

function clearValidationError() {
  message.textContent = '';
  message.hidden = true;
}

function calculateScore() {
  return questionNames.reduce((total, name) => total + (getSelectedValue(name) === answers[name] ? 1 : 0), 0);
}

function displayScore(score) {
  scoreValue.textContent = String(score);
  scoreElement.dataset.score = String(score);
  scoreElement.hidden = false;
  resultHeading.hidden = false;
}

function handleSubmit(event) {
  event.preventDefault();
  const complete = questionNames.every((name) => getSelectedValue(name) !== null);
  if (!complete) {
    showValidationError();
    return;
  }
  clearValidationError();
  displayScore(calculateScore());
}

form.addEventListener('submit', handleSubmit);
